    "dailymed-methylene-blue": { label: "DailyMed methylene blue injection prescribing information", url: "https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=eb87d31c-3a8e-4089-9693-20bc17279650&version=3" },
